export const triageCasesExpansion = [
{ id:"tx13",title:"Acute ischemic stroke",scenario:"A patient arrives with sudden aphasia and right arm weakness.",steps:["Establish last-known-well time, activate stroke response, and assess ABCs.","Check bedside glucose and obtain focused neurologic assessment/NIHSS.","Obtain urgent noncontrast head CT and vascular imaging when indicated.","Determine eligibility for IV thrombolysis and/or thrombectomy; avoid treatment delays."]},
{ id:"tx14",title:"Anaphylaxis after infusion",scenario:"A patient develops urticaria, wheezing, and hypotension during an IV infusion.",steps:["Stop the suspected trigger and call for emergency assistance.","Administer intramuscular epinephrine promptly.","Position supine when tolerated, support airway/oxygenation, and give IV crystalloid for shock.","Reassess frequently, repeat epinephrine if needed, and arrange observation."]},
{ id:"tx15",title:"Upper GI hemorrhage",scenario:"A patient with melena becomes tachycardic and hypotensive.",steps:["Assess airway and circulation; call for help and establish large-bore IV access.","Begin hemodynamic resuscitation and send CBC, coagulation studies, type and crossmatch.","Start cause-directed initial therapy when indicated, including PPI or variceal-bleed regimen.","Arrange urgent endoscopy after initial stabilization and reassess ongoing bleeding."]},
{ id:"tx16",title:"Acute asthma exacerbation",scenario:"A patient is wheezing, using accessory muscles, and speaking in short phrases.",steps:["Assess severity, oxygenation, and ability to speak; give oxygen as needed.","Administer repeated inhaled short-acting beta agonist and add ipratropium for severe attack.","Give systemic glucocorticoid early.","Reassess work of breathing and peak flow; escalate to magnesium or ventilatory support if refractory."]},
{ id:"tx17",title:"Severe hyperkalemia",scenario:"A patient with renal failure has potassium 7.0 mEq/L and QRS widening.",steps:["Place on cardiac monitor and obtain IV access; confirm but do not delay emergency treatment.","Give IV calcium to stabilize cardiac membranes.","Shift potassium intracellularly with insulin/dextrose and inhaled beta agonist; consider bicarbonate in selected acidosis.","Arrange definitive potassium removal and repeat ECG/electrolytes."]},
{ id:"tx18",title:"Suspected ectopic pregnancy",scenario:"A patient with positive pregnancy test has pelvic pain and hypotension.",steps:["Assess hemodynamic status, obtain IV access, and initiate resuscitation.","Obtain urgent bedside pelvic ultrasound and focused evaluation for hemoperitoneum.","Call obstetrics/gynecology and prepare for operative management if rupture or instability is suspected.","Provide blood products and definitive hemorrhage control as indicated."]},
{ id:"tx19",title:"Acute compartment syndrome",scenario:"A patient with a tibial fracture has escalating pain and pain with passive toe stretch.",steps:["Recognize the limb-threatening syndrome and remove constrictive dressings/splints.","Perform and document serial neurovascular examinations; keep limb at heart level.","Obtain immediate orthopedic consultation; do not delay for imaging if clinical suspicion is high.","Proceed to emergent fasciotomy when indicated and reassess perfusion."]},
{ id:"tx20",title:"Febrile neutropenia",scenario:"A patient receiving chemotherapy has temperature 38.5°C and ANC 300/µL.",steps:["Recognize high-risk febrile neutropenia and assess for sepsis or instability.","Obtain blood cultures from peripheral and central access promptly if this does not delay therapy.","Administer empiric antipseudomonal IV antibiotics rapidly.","Risk-stratify, monitor closely, and tailor treatment to cultures and clinical course."]},
{ id:"tx21",title:"Acute pulmonary edema",scenario:"A patient has severe dyspnea, hypoxemia, crackles, and hypertension.",steps:["Sit upright, assess airway and oxygenation, and attach cardiac monitoring.","Provide oxygen and noninvasive positive-pressure ventilation when appropriate.","Treat precipitating cause and reduce afterload with nitrates when blood pressure allows; use diuretics for congestion.","Reassess respiratory effort, hemodynamics, urine output, and response."]},
{ id:"tx22",title:"Suspected aortic dissection",scenario:"A patient has abrupt tearing chest and back pain with pulse asymmetry.",steps:["Assess stability, establish IV access, and place on continuous monitoring.","Control heart rate with IV beta blockade unless contraindicated; then address blood pressure.","Obtain urgent CT angiography in a stable patient or bedside TEE when unstable/unavailable.","Consult cardiothoracic/vascular surgery urgently and arrange definitive management."]},
{ id:"tx23",title:"Meningococcal sepsis",scenario:"A febrile patient has purpura, hypotension, and altered mental status.",steps:["Initiate sepsis resuscitation and institute droplet precautions.","Obtain blood cultures if this does not delay treatment.","Give immediate empiric IV antibiotics appropriate for suspected meningococcemia.","Support perfusion, monitor for DIC/organ failure, and notify public health as required."]},
{ id:"tx24",title:"Status epilepticus",scenario:"A patient has continuous generalized convulsions for more than five minutes.",steps:["Protect from injury, call resuscitation support, and assess ABCs.","Check point-of-care glucose and correct hypoglycemia if present.","Give an adequate benzodiazepine dose promptly.","Load a longer-acting antiseizure medication if seizures persist and evaluate the cause."]},
{ id:"tx25",title:"Acute urinary retention",scenario:"An older adult has painful suprapubic distention and cannot void.",steps:["Assess stability, pain, and possible neurologic red flags.","Perform bladder scan when available and assess for reversible medication or obstructive causes.","Decompress the bladder with urethral catheterization unless contraindicated.","Monitor urine output, renal function, hematuria, and plan cause-directed follow-up."]},
{ id:"tx26",title:"Diabetic hypoglycemia",scenario:"A patient with diabetes is diaphoretic and confused; bedside glucose is 38 mg/dL.",steps:["Assess airway and ability to swallow safely.","Give oral fast-acting carbohydrate if alert and able to swallow; otherwise give IV dextrose or IM glucagon.","Recheck glucose promptly and repeat treatment if still low.","Identify precipitant, provide sustained carbohydrate/meal, and adjust medications safely."]},
{ id:"tx27",title:"Postpartum hemorrhage",scenario:"A patient has heavy bleeding after delivery and a boggy uterus.",steps:["Call for help, quantify blood loss, and assess ABCs; establish large-bore IV access.","Perform uterine massage and administer oxytocin promptly.","Evaluate the four Ts and give additional uterotonics, tranexamic acid, or blood products as indicated.","Escalate to balloon tamponade or procedural/surgical control if bleeding persists."]},
{ id:"tx28",title:"Acute angle-closure glaucoma",scenario:"A patient has severe eye pain, halos, vomiting, and a fixed mid-dilated pupil.",steps:["Recognize a vision-threatening emergency and obtain urgent ophthalmology help.","Begin immediate pressure-lowering therapy per protocol, including topical agents and systemic acetazolamide when appropriate.","Use additional agents such as hyperosmotic therapy if pressure remains severe and patient factors allow.","Arrange definitive laser peripheral iridotomy after pressure control."]},
{ id:"tx29",title:"Tension pneumothorax",scenario:"A trauma patient is hypotensive with severe respiratory distress and unilateral absent breath sounds.",steps:["Recognize the clinical pattern and call for immediate resuscitation support.","Perform immediate needle or finger thoracostomy without waiting for imaging.","Place a definitive chest tube after decompression.","Reassess ventilation, hemodynamics, and associated injuries."]},
{ id:"tx30",title:"Acute bacterial meningitis",scenario:"A febrile patient has headache, neck stiffness, and confusion without focal deficits.",steps:["Stabilize airway, breathing, circulation, and obtain IV access.","Obtain blood cultures promptly if this does not delay treatment.","Start empiric IV antibiotics and adjunctive dexamethasone when indicated; add age/risk-specific coverage.","Perform lumbar puncture promptly when safe and tailor treatment to CSF and cultures."]},
{ id:"tx31",title:"Heat stroke",scenario:"A runner collapses in hot weather with confusion and core temperature 41°C.",steps:["Recognize heat stroke and initiate rapid active cooling immediately.","Assess ABCs, obtain IV access, and monitor core temperature and cardiac rhythm.","Continue cooling while checking glucose, electrolytes, renal function, CK, and coagulation.","Stop active cooling near target temperature and monitor for multiorgan complications."]},
{ id:"tx32",title:"Acute limb ischemia",scenario:"A patient develops sudden severe leg pain, pallor, coolness, and absent distal pulses.",steps:["Recognize the six Ps, assess limb viability, and obtain urgent vascular consultation.","Start systemic IV unfractionated heparin unless contraindicated.","Perform urgent arterial imaging if it will not delay revascularization in a threatened limb.","Proceed to urgent revascularization and monitor for reperfusion injury/compartment syndrome."]}
];

